function clampCanvasZoom(value: number) {
  return Math.min(CANVAS_MAX_ZOOM, Math.max(CANVAS_MIN_ZOOM, Number(value.toFixed(2))));
}

function clampAssetManagerWidth(value: number) {
  return Math.min(ASSET_MANAGER_MAX_WIDTH, Math.max(ASSET_MANAGER_MIN_WIDTH, Math.round(value)));
}

function arrangeNodesForPreview(nodes: CloneNode[]) {
  if (nodes.length <= 1) return nodes;
  const orderedNodes = [...nodes].sort((first, second) => first.y - second.y || first.x - second.x);
  const columns = Math.max(1, Math.ceil(Math.sqrt(nodes.length * 1.2)));
  const cellWidth = Math.max(360, ...nodes.map((node) => node.width)) + OFFICIAL_NODE_GAP;
  const cellHeight = Math.max(260, ...nodes.map((node) => node.height)) + OFFICIAL_NODE_GAP;
  const arrangedById = new Map<string, Pick<CloneNode, "x" | "y">>();

  orderedNodes.forEach((node, index) => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    arrangedById.set(node.id, {
      x: column * cellWidth,
      y: row * cellHeight,
    });
  });

  return nodes.map((node) => {
    const arranged = arrangedById.get(node.id);
    return arranged ? { ...node, ...arranged } : node;
  });
}
