function ZoomDock({
  assetManagerOpen = false,
  assetManagerWidth = ASSET_MANAGER_DEFAULT_WIDTH,
  compact = false,
  edgesHidden = false,
  nodes = [],
  onArrange,
  onCenter,
  onSetZoom,
  onToggleEdges,
  onToggleAssetManager,
  onToggleOverview,
  onToggleSnap,
  onViewportChange,
  overviewOpen = false,
  selectedNodeId,
  snapEnabled = true,
  viewport,
  onZoomIn,
  onZoomOut,
  zoom,
}: {
  assetManagerOpen?: boolean;
  assetManagerWidth?: number;
  compact?: boolean;
  edgesHidden?: boolean;
  nodes?: CloneNode[];
  onArrange: () => void;
  onCenter: () => void;
  onToggleEdges?: () => void;
  onToggleAssetManager?: () => void;
  onToggleOverview?: () => void;
  onToggleSnap?: () => void;
  onSetZoom: (zoom: number) => void;
  onViewportChange: (viewport: { x: number; y: number; zoom: number }) => void;
  overviewOpen?: boolean;
  selectedNodeId?: string | null;
  snapEnabled?: boolean;
  viewport: { x: number; y: number; zoom: number };
  onZoomIn: () => void;
  onZoomOut: () => void;
  zoom: number;
}) {
  const zoomMenuRef = useRef<HTMLDivElement | null>(null);
  const zoomPercent = Math.round(zoom * 100);
  const [zoomMenuOpen, setZoomMenuOpen] = useState(false);
  const [zoomInputValue, setZoomInputValue] = useState(() => String(zoomPercent));

  useEffect(() => {
    setZoomInputValue(String(zoomPercent));
  }, [zoomPercent]);

  useEffect(() => {
    if (!zoomMenuOpen) return;
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target;
      if (target instanceof Node && zoomMenuRef.current?.contains(target)) return;
      setZoomMenuOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setZoomMenuOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [zoomMenuOpen]);

  const applyZoom = useCallback(
    (nextZoom: number) => {
      const clampedZoom = clampCanvasZoom(nextZoom);
      setZoomInputValue(String(Math.round(clampedZoom * 100)));
      onSetZoom(clampedZoom);
    },
    [onSetZoom]
  );

  const commitZoomInput = useCallback(() => {
    const parsedPercent = Number.parseFloat(zoomInputValue.trim().replace("%", ""));
    if (!Number.isFinite(parsedPercent)) {
      setZoomInputValue(String(zoomPercent));
      return;
    }
    applyZoom(parsedPercent / 100);
  }, [applyZoom, zoomInputValue, zoomPercent]);

  const renderZoomMenuItem = (label: string, shortcut: string | null, onClick: () => void) => (
    <button
      className="flex h-9 w-full cursor-pointer items-center justify-between rounded-lg px-[9px] text-left text-[13px] leading-none text-white/88 transition-colors hover:bg-white/10 hover:text-white"
      key={label}
      onClick={onClick}
      role="menuitem"
      type="button"
    >
      <span>{label}</span>
      {shortcut ? <span className="text-white/38">{shortcut}</span> : null}
    </button>
  );

  const zoomButtonWidth = zoomPercent < 100 ? 36 : zoomPercent >= 800 ? 44 : 42;

  if (compact) {
    return (
      <div
        className="fixed bottom-4 left-0 z-40 flex items-center gap-1 rounded-r-xl border border-l-0 border-white/9 bg-[var(--video-surface-202020)]/95 p-1.5 text-white/70 shadow-[0_18px_48px_rgba(0,0,0,0.42)] backdrop-blur-[8px]"
        data-canvas-overlay="true"
      >
        <button className="flex h-7 w-10 items-center justify-center rounded-lg bg-white/10 transition-colors hover:bg-white/14" type="button">
          <MagnetGlyph />
        </button>
        <button className="flex h-7 w-10 items-center justify-center rounded-lg text-[18px] leading-none transition-colors hover:bg-white/10" onClick={onZoomOut} type="button">
          -
        </button>
        <button className="h-7 min-w-[72px] rounded-lg px-1 text-[13px] leading-normal transition-colors hover:bg-white/10" onClick={onCenter} type="button">
          77%
        </button>
        <button className="flex h-7 w-10 items-center justify-center rounded-lg text-[18px] leading-none transition-colors hover:bg-white/10" onClick={onZoomIn} type="button">
          +
        </button>
      </div>
    );
  }

  return (
    <div className="fixed bottom-3 left-4 z-40 flex items-end gap-2" data-canvas-overlay="true">
      <div
        className="flex items-center gap-1 rounded-xl bg-[var(--video-surface-141414)]/70 p-[6px] text-white/74 shadow-[0_18px_48px_rgba(0,0,0,0.38)] backdrop-blur-[10px]"
        style={{ transform: assetManagerOpen ? `translateX(${assetManagerWidth}px)` : undefined }}
      >
        {assetManagerOpen ? null : (
          <ZoomDockButton label="资产管理" onClick={onToggleAssetManager} wide>
            <AssetGlyph />
          </ZoomDockButton>
        )}
        <ZoomDockButton label="整理画布，Option+Shift+F" onClick={onArrange}>
          <ArrangeCanvasGlyph />
        </ZoomDockButton>
        <div className="relative h-7 w-7">
          {overviewOpen ? (
            <CanvasOverviewPopover
              nodes={nodes}
              selectedNodeId={selectedNodeId || null}
              viewport={viewport}
              onViewportChange={onViewportChange}
            />
          ) : null}
          <ZoomDockButton active={overviewOpen} label="切换小地图" onClick={onToggleOverview}>
            <GridTilesGlyph />
          </ZoomDockButton>
        </div>
        <ZoomDockButton active={edgesHidden} label={edgesHidden ? "显示节点连线" : "隐藏节点连线"} onClick={onToggleEdges}>
          <EdgeVisibilityGlyph hidden={edgesHidden} />
        </ZoomDockButton>
        <ZoomDockButton label="网格吸附" onClick={onToggleSnap}>
          <MagnetGlyph />
        </ZoomDockButton>
        <div className="relative h-7" ref={zoomMenuRef} style={{ width: zoomButtonWidth }}>
          {zoomMenuOpen ? (
            <div
              aria-label="缩放选项"
              className="absolute bottom-9 left-[-72px] z-[300] w-[187px] rounded-xl border-[0.5px] border-[#363636] bg-[var(--video-surface-262626)] p-[6px] text-[13px] text-white shadow-[0_8px_32px_rgba(0,0,0,0.15),0_2px_8px_rgba(0,0,0,0.1)]"
              role="menu"
            >
              <label className="mb-[6px] flex h-8 w-full items-center rounded-lg bg-white/10 px-[9px] text-white/88">
                <input
                  aria-label="缩放比例"
                  className="h-5 min-w-0 flex-1 bg-transparent text-[13px] leading-5 text-white outline-none placeholder:text-white/30"
                  inputMode="decimal"
                  onChange={(event) => setZoomInputValue(event.target.value.replace(/[^\d.]/g, ""))}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitZoomInput();
                    }
                  }}
                  value={zoomInputValue}
                />
                <span className="pl-1 text-white/60">%</span>
              </label>
              {renderZoomMenuItem("放大", "⌘+", () => applyZoom(zoom + CANVAS_ZOOM_STEP))}
              {renderZoomMenuItem("缩小", "⌘-", () => applyZoom(zoom - CANVAS_ZOOM_STEP))}
              {renderZoomMenuItem("适合屏幕", "⌘0", onCenter)}
              <div className="mx-1 my-[5px] h-px bg-white/10" />
              {renderZoomMenuItem("缩放至50%", null, () => applyZoom(0.5))}
              {renderZoomMenuItem("缩放至100%", null, () => applyZoom(1))}
              {renderZoomMenuItem("缩放至800%", null, () => applyZoom(8))}
            </div>
          ) : null}
          <button
            aria-expanded={zoomMenuOpen}
            aria-haspopup="menu"
            aria-label="缩放选项"
            className="flex h-7 cursor-pointer items-center justify-center rounded-lg px-1 text-[13px] leading-normal text-white/84 transition-colors hover:bg-white/10 hover:text-white"
            onClick={() => setZoomMenuOpen((value) => !value)}
            style={{ width: zoomButtonWidth }}
            title="缩放选项"
            type="button"
          >
            {zoomPercent}%
          </button>
        </div>
      </div>
    </div>
  );
}

