function CanvasOverviewPopover({
  nodes,
  onViewportChange,
  selectedNodeId,
  viewport,
}: {
  nodes: CloneNode[];
  onViewportChange: (viewport: { x: number; y: number; zoom: number }) => void;
  selectedNodeId: string | null;
  viewport: { x: number; y: number; zoom: number };
}) {
  const [draggingPointerId, setDraggingPointerId] = useState<number | null>(null);
  const map = useMemo(() => {
    if (nodes.length === 0) return null;
    const minX = Math.min(...nodes.map((node) => node.x));
    const minY = Math.min(...nodes.map((node) => node.y));
    const maxX = Math.max(...nodes.map((node) => node.x + node.width));
    const maxY = Math.max(...nodes.map((node) => node.y + node.height));
    const width = Math.max(1, maxX - minX);
    const height = Math.max(1, maxY - minY);
    const scale = Math.min(130 / width, 90 / height);
    const renderedWidth = width * scale;
    const renderedHeight = height * scale;
    return {
      height,
      minX,
      minY,
      offsetX: (150 - renderedWidth) / 2,
      offsetY: (110 - renderedHeight) / 2,
      scale,
      width,
    };
  }, [nodes]);

  const panToMiniPoint = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (!map) return;
      const rect = event.currentTarget.getBoundingClientRect();
      const worldX = map.minX + (event.clientX - rect.left - map.offsetX) / map.scale;
      const worldY = map.minY + (event.clientY - rect.top - map.offsetY) / map.scale;
      onViewportChange({
        x: Math.round(window.innerWidth / 2 - worldX * viewport.zoom),
        y: Math.round(window.innerHeight / 2 - worldY * viewport.zoom),
        zoom: viewport.zoom,
      });
    },
    [map, onViewportChange, viewport.zoom]
  );

  const viewportWidth = typeof window === "undefined" ? 0 : window.innerWidth;
  const viewportHeight = typeof window === "undefined" ? 0 : window.innerHeight;
  const miniViewBox = map
    ? {
        height: 110 / map.scale,
        width: 150 / map.scale,
        x: map.minX - map.offsetX / map.scale,
        y: map.minY - map.offsetY / map.scale,
      }
    : null;
  const viewportWorldRect = map && viewportWidth > 0 && viewportHeight > 0
    ? {
        height: viewportHeight / viewport.zoom,
        left: -viewport.x / viewport.zoom,
        top: -viewport.y / viewport.zoom,
        width: viewportWidth / viewport.zoom,
      }
    : null;
  const minimapMaskPath =
    miniViewBox && viewportWorldRect
      ? [
          `M${miniViewBox.x},${miniViewBox.y}h${miniViewBox.width}v${miniViewBox.height}h-${miniViewBox.width}z`,
          `M${viewportWorldRect.left},${viewportWorldRect.top}h${viewportWorldRect.width}v${viewportWorldRect.height}h-${viewportWorldRect.width}z`,
        ].join("\n        ")
      : "";

  return (
    <div className="absolute bottom-9 left-0 z-50 rounded-xl">
      <div
        aria-label="Mini Map"
        className="react-flow__panel react-flow__minimap bottom right relative h-[110px] w-[150px] rounded-xl text-transparent"
        onPointerDown={(event) => {
          event.preventDefault();
          event.stopPropagation();
          event.currentTarget.setPointerCapture(event.pointerId);
          setDraggingPointerId(event.pointerId);
          panToMiniPoint(event);
        }}
        onPointerMove={(event) => {
          if (draggingPointerId !== event.pointerId) return;
          event.preventDefault();
          event.stopPropagation();
          panToMiniPoint(event);
        }}
        onPointerUp={(event) => {
          if (draggingPointerId === event.pointerId) {
            event.currentTarget.releasePointerCapture(event.pointerId);
            setDraggingPointerId(null);
          }
        }}
      >
        <span className="sr-only">Mini Map</span>
        {map && miniViewBox ? (
          <svg
            className="react-flow__minimap-svg"
            height={110}
            role="img"
            viewBox={`${miniViewBox.x} ${miniViewBox.y} ${miniViewBox.width} ${miniViewBox.height}`}
            width={150}
          >
            <title>Mini Map</title>
            {nodes.map((node) => (
              <rect
                className={cn("react-flow__minimap-node", node.id === selectedNodeId && "selected")}
                height={node.height}
                key={node.id}
                rx={2}
                ry={2}
                style={{
                  fill:
                    node.id === selectedNodeId
                      ? "rgba(255,255,255,0.46)"
                      : "var(--canvas-minimap-node, rgba(255,255,255,0.22))",
                }}
                width={node.width}
                x={node.x}
                y={node.y}
              />
            ))}
            {minimapMaskPath ? (
              <path
                className="react-flow__minimap-mask"
                d={minimapMaskPath}
                fillRule="evenodd"
                pointerEvents="none"
                style={{ fill: "rgba(255,255,255,0.04)" }}
              />
            ) : null}
          </svg>
        ) : null}
      </div>
    </div>
  );
}

function StylizedBrandLogo({
  siteLogo,
  siteLogoDark,
  siteName,
}: {
  siteLogo?: string | null;
  siteLogoDark?: string | null;
  siteName?: string | null;
}) {
  const resolvedSiteName = resolveSiteName(siteName);
  const { resolvedTheme } = useTheme();
  const displayLogo = resolveDefaultSiteLogo(resolvedTheme === "dark" ? siteLogoDark || siteLogo : siteLogo);

  return (
    <span className="flex min-w-0 items-center gap-2.5">
      {displayLogo ? (
        <img
          alt={resolvedSiteName}
          className={cn("h-8 w-8 shrink-0 object-contain", shouldInvertDefaultLogoForTheme(displayLogo, resolvedTheme) && "brightness-0")}
          src={displayLogo}
        />
      ) : (
        <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-white/10">
          <Wand2 className="h-4 w-4 text-white" />
        </span>
      )}
      <span className="max-w-[140px] truncate text-base font-semibold text-white">
        {resolvedSiteName}
      </span>
    </span>
  );
}

