function VideoCropSelectionOverlay({
  anchor,
  node,
}: {
  anchor: PresetControlAnchor;
  node: CloneNode;
}) {
  const nodeWidth = Math.max(1, node.width * anchor.zoom);
  const nodeHeight = Math.max(1, node.height * anchor.zoom);
  const cardTop = anchor.topY + 32 * anchor.zoom;
  const cardHeight = Math.max(1, nodeHeight - 32 * anchor.zoom);
  const cardLeft = anchor.centerX - nodeWidth / 2;
  const cropLeft = cardLeft + nodeWidth * VIDEO_CROP_RECT.x;
  const cropTop = cardTop + cardHeight * VIDEO_CROP_RECT.y;
  const cropWidth = nodeWidth * VIDEO_CROP_RECT.width;
  const cropHeight = cardHeight * VIDEO_CROP_RECT.height;
  const handlePoints = [
    ["left-0 top-0 -translate-x-1/2 -translate-y-1/2"],
    ["left-1/2 top-0 -translate-x-1/2 -translate-y-1/2"],
    ["right-0 top-0 translate-x-1/2 -translate-y-1/2"],
    ["right-0 top-1/2 -translate-y-1/2 translate-x-1/2"],
    ["right-0 bottom-0 translate-x-1/2 translate-y-1/2"],
    ["left-1/2 bottom-0 -translate-x-1/2 translate-y-1/2"],
    ["left-0 bottom-0 -translate-x-1/2 translate-y-1/2"],
    ["left-0 top-1/2 -translate-x-1/2 -translate-y-1/2"],
  ];

  return (
    <div className="pointer-events-none absolute inset-0 z-[31]">
      <div
        className="absolute rounded-[4px] border border-white/78 bg-black/10 shadow-[0_0_0_9999px_rgba(0,0,0,0.34)]"
        style={{ height: cropHeight, left: cropLeft, top: cropTop, width: cropWidth }}
      >
        <span className="absolute left-2 top-2 rounded-[5px] bg-black/58 px-1.5 py-0.5 text-[10px] text-white/82">
          {VIDEO_CROP_INLINE_LABEL}
        </span>
        {handlePoints.map(([className]) => (
          <span
            className={cn("absolute h-2 w-2 rounded-full border border-white bg-[var(--video-surface-1f1f1f)]", className)}
            key={className}
          />
        ))}
      </div>
    </div>
  );
}

function clampUnit(value: number) {
  return Math.min(1, Math.max(0, value));
}

function getVideoCardOverlayRect(anchor: PresetControlAnchor, node: CloneNode) {
  const nodeWidth = Math.max(1, node.width * anchor.zoom);
  const nodeHeight = Math.max(1, node.height * anchor.zoom);
  const cardTop = anchor.topY + 32 * anchor.zoom;
  const cardHeight = Math.max(1, nodeHeight - 32 * anchor.zoom);
  return {
    height: cardHeight,
    left: anchor.centerX - nodeWidth / 2,
    top: cardTop,
    width: nodeWidth,
  };
}

function normalizeSubtitleEraseRegion(
  startX: number,
  startY: number,
  currentX: number,
  currentY: number,
  id: string
): SubtitleEraseRegion {
  const x = clampUnit(Math.min(startX, currentX));
  const y = clampUnit(Math.min(startY, currentY));
  const maxX = clampUnit(Math.max(startX, currentX));
  const maxY = clampUnit(Math.max(startY, currentY));
  return {
    height: Math.max(0, maxY - y),
    id,
    width: Math.max(0, maxX - x),
    x,
    y,
  };
}

function VideoSubtitleEraseRegionOverlay({
  anchor,
  node,
  onAddRegion,
  regions,
}: {
  anchor: PresetControlAnchor;
  node: CloneNode;
  onAddRegion: (region: SubtitleEraseRegion) => void;
  regions: SubtitleEraseRegion[];
}) {
  const [draftRegion, setDraftRegion] = useState<{
    currentX: number;
    currentY: number;
    pointerId: number;
    startX: number;
    startY: number;
  } | null>(null);
  const cardRect = getVideoCardOverlayRect(anchor, node);
  const toNormalizedPoint = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => ({
      x: clampUnit((event.clientX - cardRect.left) / cardRect.width),
      y: clampUnit((event.clientY - cardRect.top) / cardRect.height),
    }),
    [cardRect.height, cardRect.left, cardRect.top, cardRect.width]
  );
  const renderedRegions = draftRegion
    ? [
        ...regions,
        normalizeSubtitleEraseRegion(
          draftRegion.startX,
          draftRegion.startY,
          draftRegion.currentX,
          draftRegion.currentY,
          "draft"
        ),
      ]
    : regions;
  const handlePoints = [
    "left-0 top-0 -translate-x-1/2 -translate-y-1/2 cursor-nw-resize",
    "right-0 top-0 translate-x-1/2 -translate-y-1/2 cursor-ne-resize",
    "right-0 bottom-0 translate-x-1/2 translate-y-1/2 cursor-se-resize",
    "left-0 bottom-0 -translate-x-1/2 translate-y-1/2 cursor-sw-resize",
  ];

  return (
    <div className="pointer-events-none absolute inset-0 z-[31]" data-video-subtitle-region-overlay="true">
      <div
        className="pointer-events-auto absolute cursor-crosshair overflow-hidden rounded-[12px]"
        onPointerDown={(event) => {
          if (event.button !== 0) return;
          event.preventDefault();
          event.stopPropagation();
          const point = toNormalizedPoint(event);
          event.currentTarget.setPointerCapture(event.pointerId);
          setDraftRegion({
            currentX: point.x,
            currentY: point.y,
            pointerId: event.pointerId,
            startX: point.x,
            startY: point.y,
          });
        }}
        onPointerMove={(event) => {
          if (!draftRegion || draftRegion.pointerId !== event.pointerId) return;
          event.preventDefault();
          event.stopPropagation();
          const point = toNormalizedPoint(event);
          setDraftRegion((current) =>
            current && current.pointerId === event.pointerId
              ? { ...current, currentX: point.x, currentY: point.y }
              : current
          );
        }}
        onPointerUp={(event) => {
          if (!draftRegion || draftRegion.pointerId !== event.pointerId) return;
          event.preventDefault();
          event.stopPropagation();
          const point = toNormalizedPoint(event);
          const region = normalizeSubtitleEraseRegion(
            draftRegion.startX,
            draftRegion.startY,
            point.x,
            point.y,
            makeId("subtitle-region")
          );
          setDraftRegion(null);
          if (region.width >= 0.015 && region.height >= 0.015) {
            onAddRegion(region);
          }
        }}
        style={{
          height: cardRect.height,
          left: cardRect.left,
          top: cardRect.top,
          width: cardRect.width,
        }}
      >
        {renderedRegions.map((region) => (
          <div
            className="absolute border border-[#0690ae] bg-brand-accent/15"
            key={region.id}
            style={{
              height: `${region.height * 100}%`,
              left: `${region.x * 100}%`,
              top: `${region.y * 100}%`,
              width: `${region.width * 100}%`,
            }}
          >
            {handlePoints.map((className) => (
              <span
                className={cn("absolute h-1.5 w-1.5 rounded-full bg-brand-accent", className)}
                key={className}
              />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

