type PresetFloatingToolbarItem =
  | [string, string]
  | {
      label: string;
      message?: string;
      onClick?: () => void;
    };

function PresetFloatingToolbar({
  anchor,
  compact = false,
  items,
}: {
  anchor?: PresetControlAnchor;
  compact?: boolean;
  items: PresetFloatingToolbarItem[];
}) {
  return (
    <div
      className={cn(
        "pointer-events-auto absolute flex items-center border border-white/8 bg-[var(--video-surface-262626)]/96 text-white/78 shadow-[0_20px_64px_rgba(0,0,0,0.42)] backdrop-blur-[10px]",
        compact
          ? "h-[41px] w-[393px] gap-1 rounded-[8px] px-1"
          : "h-[58px] gap-2 rounded-[16px] px-4"
      )}
      style={
        anchor
          ? {
              left: anchor.centerX,
              top: anchor.topY - (compact ? 10 : 24 * anchor.zoom + 10),
              transform: compact
                ? "translateX(-50%) translateY(-100%)"
                : `translateX(-50%) translateY(-100%) scale(${OFFICIAL_IMAGE_TOOLBAR_SCALE})`,
              transformOrigin: "bottom center",
            }
          : { left: "50%", top: 94, transform: "translateX(-50%)" }
      }
    >
      {items.map((item) => {
        const label = Array.isArray(item) ? item[0] : item.label;
        const message = Array.isArray(item) ? item[1] : item.message;
        const onClick = Array.isArray(item) ? undefined : item.onClick;
        const compactWidth =
          label === "批量生成分镜" ? 122 : label === "批量生视频" ? 109 : 96;
        return (
          <button
            className={cn(
              "flex items-center justify-center rounded-[8px] hover:bg-white/8 hover:text-white",
              compact ? "h-8 text-[14px] font-medium" : "h-10 gap-2 rounded-[10px] px-3 text-[15px]"
            )}
            key={label}
            onClick={() => {
              if (onClick) {
                onClick();
                return;
              }
              if (message) toast.info(message);
            }}
            style={compact ? { width: compactWidth } : undefined}
            type="button"
          >
            {!compact ? (
              <span className="flex h-5 w-5 items-center justify-center rounded-[5px] border border-white/18 text-[11px] text-white/58">
                {label.slice(0, 1)}
              </span>
            ) : null}
            {label}
          </button>
        );
      })}
    </div>
  );
}

