function PresetComposerPanel({
  anchor,
  billingDefinition,
  defaultModel = "auto",
  membershipSummary,
  modelKind = "image",
  modelOptions = [],
  onSubmit,
  onDraftChange,
  prompt,
  submitMessage,
  thumbnailUrl,
  title,
}: {
  anchor?: PresetControlAnchor;
  billingDefinition?: VideoCanvasFunctionDefinition;
  defaultModel?: string;
  membershipSummary?: MembershipSummaryResponse;
  modelKind?: CanvasModelKind;
  modelOptions?: CanvasModelOption[];
  onSubmit?: (prompt: string, settings?: ComposerSettings) => void;
  onDraftChange?: (prompt: string) => void;
  prompt: string;
  submitMessage: string;
  thumbnailUrl?: string;
  title: string;
}) {
  const [menu, setMenu] = useState<ComposerMenu>(null);
  const [draftPrompt, setDraftPrompt] = useState(prompt);
  const [settings, setSettings] = useState<ComposerSettings>({
    camera: "摄像机",
    count: modelKind === "video" ? "1个" : "1张",
    duration: "5s",
    model: normalizeModelRef(defaultModel) || "auto",
    panorama: "全景",
    ratio: "16:9",
    resolution: modelKind === "video" ? "720P" : "2K",
  });
  const activeMenu = menu === "model" || menu === "ratio" || menu === "resolution" ? menu : null;

  useEffect(() => {
    setDraftPrompt(prompt);
  }, [prompt]);

  useEffect(() => {
    setSettings((current) => ({ ...current, model: normalizeModelRef(defaultModel) || "auto" }));
  }, [defaultModel]);

  const billingDisplay = useMemo(
    () =>
      resolveVideoCanvasBillingDisplay({
        duration: modelKind === "video" ? 5 : null,
        functionDefinition: billingDefinition,
        imageCount: 1,
        membershipSummary,
        modelKind,
        modelOptions,
        modelRef: settings.model,
        resolution: modelKind === "video" ? normalizeVideoResolutionValue(settings.resolution) : null,
      }),
    [billingDefinition, membershipSummary, modelKind, modelOptions, settings.model, settings.resolution],
  );

	return (
	  <div
	    className="pointer-events-auto absolute overflow-visible"
	    style={
	      anchor
	        ? {
	            height: PRESET_COMPOSER_BASE_HEIGHT * OFFICIAL_COMPOSER_SCALE,
	            left: anchor.centerX,
	            top: anchor.bottomY + 10,
	            transform: "translateX(-50%)",
	            width: PROMPT_COMPOSER_BASE_WIDTH * OFFICIAL_COMPOSER_SCALE,
	          }
	        : {
	            bottom: 64,
	            height: PRESET_COMPOSER_BASE_HEIGHT * OFFICIAL_COMPOSER_SCALE,
	            left: "50%",
	            transform: "translateX(-50%)",
	            width: PROMPT_COMPOSER_BASE_WIDTH * OFFICIAL_COMPOSER_SCALE,
	          }
	    }
	  >
	    <div
	      className="relative h-[238px] w-[895px] rounded-[18px] border border-white/8 bg-[var(--video-surface-262626)]/98 p-5 text-white shadow-[0_24px_84px_rgba(0,0,0,0.48)]"
	      style={{ transform: `scale(${OFFICIAL_COMPOSER_SCALE})`, transformOrigin: "top left" }}
	    >
	      {activeMenu ? (
	        <ComposerPopover
	          customOptions={
	            activeMenu === "resolution" && modelKind === "video"
	              ? [
	                  { label: "480P", value: "480P" },
	                  { label: "720P", value: "720P" },
	                  { label: "1080P", value: "1080P" },
	                ]
	              : undefined
	          }
	          menu={activeMenu}
	          modelKind={modelKind}
	          modelOptions={modelOptions}
	          onSelect={(option) => {
	            setSettings((current) => ({ ...current, [activeMenu]: option }));
	            setMenu(null);
	          }}
	        />
	      ) : null}
	      <button className="absolute right-5 top-5 text-[26px] text-white/45" onClick={() => toast.info("展开提示词编辑器待接入。")} type="button">↗</button>
	      <div className="mb-5 flex items-center gap-3">
	        <span className="rounded-[10px] border border-white/10 bg-[var(--video-surface-292929)] px-3 py-2 text-[14px] text-white/62">{title}</span>
	        {thumbnailUrl ? (
	          <div className="h-[54px] w-[54px] overflow-hidden rounded-[10px]">
	            <img alt="" className="h-full w-full object-cover" src={thumbnailUrl} />
	          </div>
	        ) : null}
	      </div>
	      <textarea
	        className="h-[78px] w-full resize-none bg-transparent text-[20px] leading-8 text-white/64 outline-none placeholder:text-white/38"
	        onChange={(event) => { setDraftPrompt(event.target.value); onDraftChange?.(event.target.value); }}
	        placeholder="描述你想要生成的画面内容，按 / 呼出指令，@引用素材"
	        value={draftPrompt}
	      />
	      <div className="absolute bottom-5 left-5 right-[84px] flex items-center gap-6 overflow-hidden text-[17px] text-white/78">
	        <ComposerControl active={menu === "model"} label={getCanvasModelDisplayName(settings.model, modelOptions)} icon="◉" dropdown onClick={() => setMenu((current) => current === "model" ? null : "model")} />
	        <ComposerControl active={menu === "ratio"} label={settings.ratio} icon="▭" dropdown onClick={() => setMenu((current) => current === "ratio" ? null : "ratio")} />
	        <ComposerControl active={menu === "resolution"} label={settings.resolution} dropdown onClick={() => setMenu((current) => current === "resolution" ? null : "resolution")} />
	        <ComposerControl label="摄像机" icon="▣" onClick={() => toast.info("镜头配置接口待接入。")} />
	        <ComposerControl label={settings.count} dropdown onClick={() => toast.info("当前仅支持单次生成 1 个结果。")} />
	        <ComposerControl
            label={billingDisplay.label}
            icon="⚡"
            muted
            onClick={() => toast.info(billingDisplay.message)}
          />
	      </div>
	      <button
	        className="absolute bottom-5 right-5 flex h-11 w-11 items-center justify-center rounded-[12px] bg-white/76 text-[24px] text-black hover:bg-white"
	        onClick={() => {
            if (onSubmit) {
              onSubmit(draftPrompt, settings);
              return;
            }
            toast.info(submitMessage);
          }}
	        type="button"
	      >
	        ↑
	      </button>
	    </div>
	  </div>
	);
}

function CharacterThreeViewScene() {
  const [toolbarMenu, setToolbarMenu] = useState<SceneToolbarMenu>(null);
  const sceneActions: Array<{
    action: Extract<ImageToolbarAction, "annotate" | "rotate" | "download" | "preview">;
    message: string;
  }> = [
    { action: "annotate", message: "绘制编辑待接入。" },
    { action: "rotate", message: "对比预览待接入。" },
    { action: "download", message: "下载素材待接入。" },
    { action: "preview", message: "全屏预览待接入。" },
  ];

  return (
    <div className="pointer-events-none absolute inset-0 z-30" data-canvas-overlay="true">
      <div className="pointer-events-auto absolute left-1/2 top-[90px] flex h-[72px] -translate-x-1/2 items-center gap-6 rounded-[18px] border border-white/8 bg-[var(--video-surface-262626)]/96 px-7 text-[18px] text-white/82 shadow-[0_20px_64px_rgba(0,0,0,0.42)] backdrop-blur-[10px]">
        <SceneTool active={toolbarMenu === "panorama"} kind="panorama" label="全景" badge="NEW" onClick={() => setToolbarMenu((current) => current === "panorama" ? null : "panorama")} />
        <SceneTool active={toolbarMenu === "orbit"} kind="orbit" label="多角度" onClick={() => setToolbarMenu((current) => current === "orbit" ? null : "orbit")} />
        <SceneTool active={toolbarMenu === "lighting"} kind="lighting" label="打光" onClick={() => setToolbarMenu((current) => current === "lighting" ? null : "lighting")} />
        <SceneTool active={toolbarMenu === "grid"} kind="grid" label="九宫格" dropdown onClick={() => setToolbarMenu((current) => current === "grid" ? null : "grid")} />
        <SceneTool active={toolbarMenu === "hd"} kind="hd" label="高清" dropdown onClick={() => setToolbarMenu((current) => current === "hd" ? null : "hd")} />
        <SceneTool active={toolbarMenu === "crop"} kind="crop" label="宫格切分" dropdown onClick={() => setToolbarMenu((current) => current === "crop" ? null : "crop")} />
        <div className="h-9 w-px bg-white/8" />
        {sceneActions.map((item) => (
          <button
            className="flex h-10 w-10 items-center justify-center rounded-[8px] text-white/84 hover:bg-white/8"
            key={item.action}
            onClick={() => toast.info(item.message)}
            type="button"
          >
            <ImageToolbarActionGlyph action={item.action} />
          </button>
        ))}
      </div>
      {toolbarMenu ? <SceneToolbarPopover menu={toolbarMenu} onClose={() => setToolbarMenu(null)} /> : null}

      <div className="pointer-events-auto absolute left-1/2 top-[174px] flex -translate-x-1/2 items-start gap-[110px]">
        <CharacterImagePanel imageUrl={CHARACTER_IMAGE_URL} label="角色图" wide />
        <div className="relative mt-[214px] w-[4px]">
          <div className="absolute right-[4px] top-0 h-[2px] w-[110px] bg-gradient-to-r from-transparent via-[#59a8ff] to-[#9bd6ff]" />
          <button
            className="absolute -left-[16px] -top-[14px] flex h-7 w-7 items-center justify-center rounded-full border border-white/45 bg-[var(--video-surface-222)] text-[22px] leading-none text-white/72"
            onClick={() => toast.info("连接素材节点接口待接入。")}
            type="button"
          >
            +
          </button>
        </div>
        <CharacterImagePanel imageUrl={CHARACTER_THREE_VIEW_URL} label="角色三视图" />
      </div>

      <PromptComposer />
    </div>
  );
}

function SceneTool({
  active,
  badge,
  dropdown,
  kind,
  label,
  onClick,
}: {
  active?: boolean;
  badge?: string;
  dropdown?: boolean;
  kind: "panorama" | "orbit" | "lighting" | "grid" | "hd" | "crop" | "localEdit";
  label: string;
  onClick: () => void;
}) {
  return (
    <button
      className={cn("flex h-10 items-center gap-2 whitespace-nowrap rounded-[8px] px-1 text-white/82 hover:bg-white/8", active && "bg-white/10 text-white")}
      onClick={onClick}
      type="button"
    >
      <SceneToolIcon kind={kind} />
      <span className="whitespace-nowrap">{label}</span>
      {badge ? (
        <span className="rounded-[7px] bg-[#0e6371] px-2 py-0.5 text-[14px] font-bold tracking-wide text-[#42eaff]">
          {badge}
        </span>
      ) : null}
      {dropdown ? <span className="text-[16px] text-white/58">⌄</span> : null}
    </button>
  );
}

function SceneToolbarPopover({
  anchor,
  menu,
  onClose,
  onSelect,
}: {
  anchor?: PresetControlAnchor;
  menu: Exclude<SceneToolbarMenu, null>;
  onClose: () => void;
  onSelect?: (option?: string) => void;
}) {
  const [lightingPrompt, setLightingPrompt] = useState("");
  const [customGridOpen, setCustomGridOpen] = useState(false);
  const popoverOffset: Record<Exclude<SceneToolbarMenu, null>, number> = {
    crop: 170,
    grid: -38,
    hd: 70,
    lighting: -145,
    orbit: -245,
    panorama: -360,
  };
  const popoverScale = (anchor ? OFFICIAL_IMAGE_TOOLBAR_SCALE : 1) * OFFICIAL_DROPDOWN_SCALE;
  const officialPopoverStyle = {
    left: anchor ? anchor.centerX + popoverOffset[menu] : `calc(50% + ${popoverOffset[menu]}px)`,
    top: anchor ? anchor.topY - (24 * anchor.zoom + 10) + 8 : 168,
    transform: `translateX(-50%) scale(${popoverScale})`,
    transformOrigin: "top center",
  };
  const popoverSurfaceStyle = {
    background: "rgba(31, 31, 31, 0.92)",
    border: "0.5px solid #363636",
    borderRadius: 12,
    boxShadow: "0 4px 10px rgba(0, 0, 0, 0.2), 0 2px 4px rgba(0, 0, 0, 0.12)",
    WebkitBackdropFilter: "blur(16px)",
    backdropFilter: "blur(16px)",
  };
  const quickOptions: Record<"orbit" | "panorama", string[]> = {
    orbit: ["正侧背三视角", "八方向参考", "环绕镜头"],
    panorama: ["全景", "半身", "近景"],
  };
  const nineGridOptions = [
    "多机位九宫格",
    "剧情推演四宫格",
    "25宫格连贯分镜",
    "电影级光影校正",
    "角色三视图生成",
    "画面推演 - 3秒后",
    "画面推演 - 5秒前",
  ];
  const hdToolOptions: Array<{ key: string; label: string; active?: boolean }> = [
    { key: "upscale", label: "高清", active: true },
    { key: "outpaint", label: "扩图" },
    { key: "repaint", label: "重绘" },
    { key: "erase", label: "擦除" },
    { key: "removeBg", label: "抠图" },
    { key: "crop", label: "裁剪" },
  ];
  const cropOptions = [
    { type: 4, label: "4宫格 (2×2)" },
    { type: 9, label: "9宫格 (3×3)" },
    { type: 16, label: "16宫格 (4×4)" },
    { type: 25, label: "25宫格 (5×5)" },
  ];

  if (menu === "lighting") {
    return (
      <div
        className="pointer-events-auto absolute z-40 w-[420px] -translate-x-1/2 p-4 text-white"
        style={{ ...officialPopoverStyle, ...popoverSurfaceStyle }}
      >
        <div className="mb-3 flex items-center justify-between">
          <div className="font-semibold text-[15px] text-white/86">打光</div>
          <button className="rounded-[8px] px-2 py-1 text-white/42 hover:bg-white/8 hover:text-white" onClick={onClose} type="button">×</button>
        </div>
        <textarea
          className="h-24 w-full resize-none rounded-[10px] border border-white/10 bg-[var(--video-surface-1d1d1d)] px-3 py-2 text-[13px] text-white/78 outline-none placeholder:text-white/34"
          onChange={(event) => setLightingPrompt(event.target.value)}
          placeholder="简单描述你想实现的打光效果，或者情绪风格"
          value={lightingPrompt}
        />
        <button
          className="mt-3 h-10 w-full rounded-[10px] bg-white font-semibold text-black hover:bg-white/90"
          onClick={() => onSelect?.(lightingPrompt.trim() || "柔和自然光")}
          type="button"
        >
          应用打光
        </button>
      </div>
    );
  }

  if (menu === "grid") {
    return (
      <div
        className="pointer-events-auto absolute z-40 flex w-[360px] -translate-x-1/2 flex-col p-3 font-sans"
        role="menu"
        style={{ ...officialPopoverStyle, ...popoverSurfaceStyle }}
      >
        {nineGridOptions.map((option) => (
          <button
            className="flex h-[70px] w-full cursor-pointer items-center gap-7 rounded-[10px] px-5 text-left transition-colors duration-200 hover:bg-white/8 active:bg-white/12"
            key={option}
            onClick={() => onSelect?.(option)}
            onPointerDown={(event) => event.stopPropagation()}
            role="menuitem"
            type="button"
          >
            <NineGridPresetGlyph />
            <span className="min-w-0 flex-1 truncate text-[25px] font-normal leading-snug text-white/86">
              {option}
            </span>
          </button>
        ))}
      </div>
    );
  }

  if (menu === "hd") {
    return (
      <div
        className="pointer-events-auto absolute z-40 flex w-[240px] -translate-x-1/2 flex-col gap-1.5 p-2 font-sans"
        role="menu"
        style={{ ...officialPopoverStyle, ...popoverSurfaceStyle }}
      >
        {hdToolOptions.map((option) => (
          <button
            className={cn(
              "flex h-[56px] w-full shrink-0 items-center gap-5 rounded-[10px] px-4 text-left text-[25px] font-normal leading-snug text-white/86 transition-colors",
              option.active ? "bg-white/16" : "hover:bg-white/8 active:bg-white/12"
            )}
            key={option.key}
            onClick={() => onSelect?.(option.label)}
            onPointerDown={(event) => event.stopPropagation()}
            role="menuitem"
            type="button"
          >
            <ImageToolMenuGlyph tool={option.key} />
            <span className="min-w-0 flex-1">{option.label}</span>
          </button>
        ))}
      </div>
    );
  }

  if (menu === "crop") {
    return (
      <div
        className="pointer-events-auto absolute z-40 flex w-[300px] -translate-x-1/2 flex-col overflow-visible p-3 font-sans"
        onMouseLeave={() => setCustomGridOpen(false)}
        role="menu"
        style={{ ...officialPopoverStyle, ...popoverSurfaceStyle }}
      >
        {cropOptions.map((option) => (
          <button
            className="flex h-[70px] w-full cursor-pointer items-center rounded-[10px] px-5 text-left transition-colors duration-200 hover:bg-white/8 active:bg-white/12"
            key={option.type}
            onClick={() => onSelect?.(option.label)}
            onPointerDown={(event) => event.stopPropagation()}
            role="menuitem"
            type="button"
          >
            <span className="min-w-0 truncate text-[25px] font-normal leading-snug text-white/86">
              {option.label}
            </span>
          </button>
        ))}
        <div className="mx-4 my-2 h-px bg-white/12" />
        <div onMouseEnter={() => setCustomGridOpen(true)}>
          <button
            className={cn(
              "flex h-[70px] w-full cursor-pointer items-center justify-between rounded-[10px] px-5 text-left transition-colors duration-200 hover:bg-white/8 active:bg-white/12",
              customGridOpen && "bg-white/8"
            )}
            onPointerDown={(event) => event.stopPropagation()}
            role="menuitem"
            type="button"
          >
            <span className="min-w-0 truncate text-[25px] font-normal leading-snug text-white/86">自定义</span>
            <ChevronDown className="h-5 w-5 shrink-0 -rotate-90 text-white/60" />
          </button>
        </div>
        {customGridOpen ? (
          <div
            className="absolute left-[calc(100%+8px)] top-0 w-[420px] p-4"
            onMouseEnter={() => setCustomGridOpen(true)}
            style={popoverSurfaceStyle}
          >
            <CustomGridPicker onSelect={(rows, columns) => onSelect?.(`${columns} x ${rows}`)} />
          </div>
        ) : null}
      </div>
    );
  }

  return (
    <div
      className="pointer-events-auto absolute z-40 w-[180px] -translate-x-1/2 p-1.5 text-white"
      style={{ ...officialPopoverStyle, ...popoverSurfaceStyle }}
    >
      {quickOptions[menu].map((option) => (
        <button
          className="flex h-9 w-full items-center justify-between rounded-[8px] px-3 text-left text-[13px] text-white/76 hover:bg-white/8 hover:text-white"
          key={option}
          onClick={() => onSelect?.(option)}
          type="button"
        >
          {option}
          <span className="text-white/28">›</span>
        </button>
      ))}
    </div>
  );
}

function NineGridPresetGlyph() {
  return (
    <svg aria-hidden="true" className="h-8 w-8 shrink-0 text-white/46" fill="none" viewBox="0 0 20 20">
      <path d="M3 7.2 10 3.4l7 3.8-7 3.8-7-3.8Z" stroke="currentColor" strokeLinejoin="round" strokeWidth="1.5" />
      <path d="m3 10.2 7 3.8 7-3.8M3 13.2l7 3.8 7-3.8" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" />
    </svg>
  );
}

