function getCanvasEdgePath(startX: number, startY: number, endX: number, endY: number) {
  const deltaX = endX - startX;
  const curve = deltaX >= 0 ? Math.max(60, 6.25 * Math.sqrt(Math.max(deltaX, 1))) : Math.max(60, Math.min(180, Math.abs(deltaX) * 0.5));
  return `M ${startX} ${startY} C ${startX + curve} ${startY}, ${endX - curve} ${endY}, ${endX} ${endY}`;
}

function getCanvasEdgeMidpoint(startX: number, startY: number, endX: number, endY: number) {
  const deltaX = endX - startX;
  const curve = deltaX >= 0 ? Math.max(60, 6.25 * Math.sqrt(Math.max(deltaX, 1))) : Math.max(60, Math.min(180, Math.abs(deltaX) * 0.5));
  const c1 = { x: startX + curve, y: startY };
  const c2 = { x: endX - curve, y: endY };
  const t = 0.5;
  const mt = 1 - t;
  const x = mt ** 3 * startX + 3 * mt ** 2 * t * c1.x + 3 * mt * t ** 2 * c2.x + t ** 3 * endX;
  const y = mt ** 3 * startY + 3 * mt ** 2 * t * c1.y + 3 * mt * t ** 2 * c2.y + t ** 3 * endY;
  const dx = 3 * mt ** 2 * (c1.x - startX) + 6 * mt * t * (c2.x - c1.x) + 3 * t ** 2 * (endX - c2.x);
  const dy = 3 * mt ** 2 * (c1.y - startY) + 6 * mt * t * (c2.y - c1.y) + 3 * t ** 2 * (endY - c2.y);
  return { angle: Math.atan2(dy, dx) * (180 / Math.PI), x, y };
}

function CloneEdges({
  edges,
  nodes,
  onDeleteEdge,
  onEdgePointerDown,
  preview,
  selectedEdgeId,
}: {
  edges: CloneEdge[];
  nodes: CloneNode[];
  onDeleteEdge: (edgeId: string) => void;
  onEdgePointerDown: (event: ReactPointerEvent<SVGPathElement>, edgeId: string) => void;
  preview?: { endX: number; endY: number; startX: number; startY: number } | null;
  selectedEdgeId?: string | null;
}) {
  const nodeMap = new Map(nodes.map((node) => [node.id, node]));
  const renderedEdges = edges
    .map((edge) => {
      const source = nodeMap.get(edge.source);
      const target = nodeMap.get(edge.target);
      if (!source || !target) return null;
      const startX = source.x + source.width;
      const startY = source.y + source.height / 2;
      const endX = target.x;
      const endY = target.y + target.height / 2;
      const path = getCanvasEdgePath(startX, startY, endX, endY);
      const selected = edge.id === selectedEdgeId;
      const midpoint = selected ? getCanvasEdgeMidpoint(startX, startY, endX, endY) : null;
      return { edge, midpoint, path, selected };
    })
    .filter(
      (
        item,
      ): item is {
        edge: CloneEdge;
        midpoint: ReturnType<typeof getCanvasEdgeMidpoint> | null;
        path: string;
        selected: boolean;
      } => item !== null,
    );

  return (
    <>
      <svg className="pointer-events-none absolute left-0 top-0 overflow-visible" style={{ height: CANVAS_EXTENT, width: CANVAS_EXTENT }}>
        {renderedEdges.map(({ edge, path, selected }) => (
          <g
            className={cn("react-flow__edge react-flow__edge-default nopan selectable", selected && "selected")}
            data-id={edge.id}
            key={edge.id}
          >
            <path
              d={path}
              fill="none"
              onPointerDown={(event) => onEdgePointerDown(event, edge.id)}
              stroke="transparent"
              strokeLinecap="round"
              strokeWidth="16"
              style={{ pointerEvents: "stroke" }}
            />
            {selected ? (
              <path
                d={path}
                fill="none"
                stroke="#a7afff"
                strokeLinecap="round"
                strokeOpacity="0.28"
                strokeWidth="8"
              />
            ) : null}
            <path
              d={path}
              fill="none"
              stroke={selected ? "#a7afff" : "#86909c"}
              strokeLinecap="round"
              strokeOpacity={selected ? "1" : "0.98"}
              strokeWidth={selected ? "2.8" : "2"}
            />
            <EdgeFlowSegments pathD={path} uniqueId={edge.id} visible />
          </g>
        ))}
        {preview ? (
          <g>
            <path
              d={getCanvasEdgePath(preview.startX, preview.startY, preview.endX, preview.endY)}
              fill="none"
              stroke="#a7afff"
              strokeDasharray="10 8"
              strokeLinecap="round"
              strokeOpacity="0.92"
              strokeWidth="2.5"
            />
            <circle cx={preview.endX} cy={preview.endY} fill="#a7afff" opacity="0.95" r="5" />
            <circle cx={preview.endX} cy={preview.endY} fill="none" opacity="0.32" r="13" stroke="#a7afff" strokeWidth="2" />
          </g>
        ) : null}
      </svg>
      <div className="pointer-events-none absolute left-0 top-0 z-[35] overflow-visible" style={{ height: CANVAS_EXTENT, width: CANVAS_EXTENT }}>
        {renderedEdges.map(({ edge, midpoint }) =>
          midpoint ? (
            <button
              className="scissors-enter pointer-events-auto absolute z-[36] flex h-12 w-12 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-[var(--video-surface-1e1e1e)]/95 text-white/70 shadow-[0_16px_42px_rgba(0,0,0,0.42)] transition hover:bg-[var(--video-surface-272727)] hover:text-white"
              key={`delete-${edge.id}`}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                onDeleteEdge(edge.id);
              }}
              onPointerDown={(event) => {
                event.preventDefault();
                event.stopPropagation();
              }}
              style={{ left: midpoint.x, top: midpoint.y }}
              title="删除连线"
              type="button"
            >
              <Scissors className="h-7 w-7" style={{ transform: `rotate(${Math.round(midpoint.angle - 90)}deg)` }} />
            </button>
          ) : null,
        )}
      </div>
    </>
  );
}

type EdgePoint = { x: number; y: number };

function getPointAtSampledLength(points: EdgePoint[], totalLength: number, length: number): EdgePoint {
  const safeLength = Math.max(0, Math.min(totalLength, length));
  const index = (points.length - 1) * Math.max(0, Math.min(1, safeLength / totalLength));
  const leftIndex = Math.floor(index);
  const ratio = index - leftIndex;
  if (leftIndex >= points.length - 1) return points[points.length - 1];
  const left = points[leftIndex];
  const right = points[leftIndex + 1];
  return {
    x: left.x + ratio * (right.x - left.x),
    y: left.y + ratio * (right.y - left.y),
  };
}

function parseSimpleEdgePath(pathD: string): { points: EdgePoint[]; totalLength: number } | null {
  const line = pathD.match(/M\s*([\d.eE+-]+)\s*[, ]\s*([\d.eE+-]+)\s*L\s*([\d.eE+-]+)\s*[, ]\s*([\d.eE+-]+)/i);
  const cubic = pathD.match(/M\s*([\d.eE+-]+)\s*[, ]\s*([\d.eE+-]+)\s*C\s*[\d.eE+-]+\s*[, ]\s*[\d.eE+-]+\s+[\d.eE+-]+\s*[, ]\s*[\d.eE+-]+\s+([\d.eE+-]+)\s*[, ]\s*([\d.eE+-]+)/i);
  const match = line || cubic;
  if (!match) return null;
  const x1 = Number.parseFloat(match[1]);
  const y1 = Number.parseFloat(match[2]);
  const x2 = Number.parseFloat(match[3]);
  const y2 = Number.parseFloat(match[4]);
  const totalLength = Math.hypot(x2 - x1, y2 - y1);
  if (totalLength <= 0) return null;
  const points = Array.from({ length: 81 }, (_, index) => {
    const ratio = index / 80;
    return { x: x1 + ratio * (x2 - x1), y: y1 + ratio * (y2 - y1) };
  });
  return { points, totalLength };
}

function sampleEdgePath(pathD: string): { points: EdgePoint[]; totalLength: number } | null {
  if (typeof document === "undefined") return null;
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("d", pathD);
  try {
    const totalLength = path.getTotalLength();
    if (totalLength <= 0.5) return parseSimpleEdgePath(pathD);
    const points = Array.from({ length: 81 }, (_, index) => {
      const point = path.getPointAtLength((index / 80) * totalLength);
      return { x: point.x, y: point.y };
    });
    return { points, totalLength };
  } catch {
    return parseSimpleEdgePath(pathD);
  }
}

function EdgeFlowSegments({
  glowScale = 1,
  pathD,
  strokeWidth = 4,
  uniqueId,
  visible,
}: {
  glowScale?: number;
  pathD: string;
  strokeWidth?: number;
  uniqueId: string;
  visible?: boolean;
}) {
  const [progress, setProgress] = useState(0);
  const sampledPath = useMemo(() => sampleEdgePath(pathD), [pathD]);
  const safeId = useMemo(() => `libtv-edge-flow-${uniqueId.replace(/[^a-zA-Z0-9_-]/g, "-")}`, [uniqueId]);
  const bounds = useMemo(() => {
    const points = sampledPath?.points || [];
    if (points.length === 0) return { height: 100, width: 100, x: 0, y: 0 };
    const padding = 20 * glowScale;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    points.forEach((point) => {
      minX = Math.min(minX, point.x);
      minY = Math.min(minY, point.y);
      maxX = Math.max(maxX, point.x);
      maxY = Math.max(maxY, point.y);
    });
    return {
      height: maxY - minY + padding * 2,
      width: maxX - minX + padding * 2,
      x: minX - padding,
      y: minY - padding,
    };
  }, [glowScale, sampledPath?.points]);

  useEffect(() => {
    if (!visible || !sampledPath) return;
    let frame = 0;
    const start = performance.now();
    const tick = () => {
      setProgress(((performance.now() - start) / 3000) % 1);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [sampledPath, visible]);

  if (!visible || !sampledPath) return null;

  const { points, totalLength } = sampledPath;
  const segmentLength = Math.max(0.12 * totalLength, 2);
  const filterId = `${safeId}-filter`;

  return (
    <g className="edge-flow-segments" style={{ pointerEvents: "none" }}>
      <defs>
        <filter
          colorInterpolationFilters="sRGB"
          filterUnits="userSpaceOnUse"
          height={bounds.height}
          id={filterId}
          width={bounds.width}
          x={bounds.x}
          y={bounds.y}
        >
          <feGaussianBlur in="SourceGraphic" result="blurOuter" stdDeviation={4 * glowScale} />
          <feFlood floodColor="rgba(100, 180, 255, 0.45)" result="floodOuter" />
          <feComposite in="blurOuter" in2="floodOuter" operator="in" result="glowOuter" />
          <feGaussianBlur in="SourceGraphic" result="blurInner" stdDeviation={1.5 * glowScale} />
          <feFlood floodColor="rgba(150, 210, 255, 0.7)" result="floodInner" />
          <feComposite in="blurInner" in2="floodInner" operator="in" result="glowInner" />
          <feMerge>
            <feMergeNode in="glowOuter" />
            <feMergeNode in="glowInner" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
      {Array.from({ length: 3 }, (_, index) => {
        const startLength = ((progress + index / 3) % 1) * totalLength;
        const start = getPointAtSampledLength(points, totalLength, startLength);
        const end = getPointAtSampledLength(points, totalLength, startLength + segmentLength);
        const segmentPath = Array.from({ length: 13 }, (__, segmentIndex) => {
          const point = getPointAtSampledLength(points, totalLength, startLength + (segmentLength * segmentIndex) / 12);
          return segmentIndex === 0 ? `M ${point.x},${point.y}` : `L ${point.x},${point.y}`;
        }).join(" ");
        const gradientId = `${safeId}-grad-${index}`;
        return (
          <g key={index}>
            <defs>
              <linearGradient gradientUnits="userSpaceOnUse" id={gradientId} x1={start.x} x2={end.x} y1={start.y} y2={end.y}>
                <stop offset="0%" stopColor="rgba(100, 180, 255, 0)" />
                <stop offset="100%" stopColor="rgba(100, 180, 255, 0.9)" />
              </linearGradient>
            </defs>
            <path
              d={segmentPath}
              fill="none"
              filter={`url(#${filterId})`}
              stroke={`url(#${gradientId})`}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={strokeWidth}
            />
          </g>
        );
      })}
    </g>
  );
}

function CloneCanvasNode({
  connectionsHidden,
  connectionHoverActive,
  onClearGridSplit,
  onClearGridSplitSelection,
  onClearLocalEditRegions,
  node,
  onCancelGeneration,
  onContextMenu,
  onExtractVideoFrame,
  onGenerateVideoHd,
  onModuleAction,
  onOpenConnectionMenu,
  onOpenScriptWorkflow,
  onPointerDown,
  onStartConnectionDrag,
  onStartConnectionMouseDrag,
  onRunNode,
  onSetLocalEditMode,
  onSubmitLocalEdit,
  onToggleGridSplitSelection,
  onUpdateLocalEditRegions,
  onTextResourceChange,
  selected,
}: {
  connectionsHidden: boolean;
  connectionHoverActive: boolean;
  onClearGridSplit: () => void;
  onClearGridSplitSelection: () => void;
  onClearLocalEditRegions: () => void;
  node: CloneNode;
  onCancelGeneration: () => void;
  onContextMenu: (event: ReactMouseEvent<HTMLDivElement>) => void;
  onExtractVideoFrame: (kind: VideoFrameExtractionKind) => void;
  onGenerateVideoHd: () => void;
  onModuleAction: (actionLabel: TargetModuleActionLabel) => void;
  onOpenConnectionMenu: (event: ReactMouseEvent<HTMLButtonElement>, side: ConnectionSide) => void;
  onOpenScriptWorkflow: () => void;
  onPointerDown: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onStartConnectionDrag: (event: ReactPointerEvent<HTMLButtonElement>, side: ConnectionSide) => void;
  onStartConnectionMouseDrag: (event: ReactMouseEvent<HTMLButtonElement>, side: ConnectionSide) => void;
  onRunNode: () => void;
  onSetLocalEditMode: (enabled: boolean) => void;
  onSubmitLocalEdit: (regions: LocalEditRegion[]) => void;
  onToggleGridSplitSelection: (index: number, behavior: "replace" | "toggle") => void;
  onUpdateLocalEditRegions: (regions: LocalEditRegion[]) => void;
  onTextResourceChange: (content: string) => void;
  selected: boolean;
}) {
  if (getDraftString(node, "action") === "TOOLBOX_TEMPLATE_GROUP") {
    return <ToolboxTemplateGroupCanvasNode node={node} selected={selected} />;
  }

  if (
    node.kind === "material-style" ||
    getDraftString(node, "action") === "MATERIAL_STYLE" ||
    isVideoEffectMaterialNode(node) ||
    isVideoRoleMaterialNode(node)
  ) {
    return (
      <MaterialStyleCanvasNode
        node={node}
        onContextMenu={onContextMenu}
        onPointerDown={onPointerDown}
        selected={selected}
      />
    );
  }

  const shellProps = {
    connectionHoverActive,
    connectionsHidden,
    node,
    onContextMenu,
    onOpenConnectionMenu,
    onPointerDown,
    onStartConnectionDrag,
    onStartConnectionMouseDrag,
    selected,
  };

  const targetModuleKind = getTargetModuleKind(node);
  if (targetModuleKind) {
    return (
      <CanvasNodeShell {...shellProps}>
        <TargetModuleCanvasNode kind={targetModuleKind} node={node} onAction={onModuleAction} selected={selected} />
      </CanvasNodeShell>
    );
  }

  if (getDraftString(node, "action") === "TEXT_RESOURCE") {
    return (
      <CanvasNodeShell {...shellProps}>
        <PureTextResourceCanvasNode node={node} onTextResourceChange={onTextResourceChange} selected={selected} />
      </CanvasNodeShell>
    );
  }

  if (node.kind === "video-story" || getDraftString(node, "action") === "VIDEO_STORY_ANALYSIS") {
    return (
      <CanvasNodeShell {...shellProps}>
        <VideoStoryCanvasNode node={node} selected={selected} />
      </CanvasNodeShell>
    );
  }

  if (
    getDraftString(node, "action") === "VIDEO_SUBTITLE_ERASE" &&
    getDraftString(node, "generationStatus") === "pending"
  ) {
    return (
      <CanvasNodeShell {...shellProps}>
        <VideoSubtitleErasePendingCanvasNode node={node} onCancel={onCancelGeneration} selected={selected} />
      </CanvasNodeShell>
    );
  }

  if (getDraftString(node, "action") === "VIDEO_HD_UPSCALE") {
    return (
      <CanvasNodeShell {...shellProps}>
        <VideoHdUpscaleCanvasNode node={node} onGenerate={onGenerateVideoHd} selected={selected} />
      </CanvasNodeShell>
    );
  }

  if (node.kind === "media") {
    return (
      <CanvasNodeShell {...shellProps}>
        <PresetMediaCanvasNode
          node={node}
          onCancelGeneration={onCancelGeneration}
          onClearGridSplit={onClearGridSplit}
          onClearGridSplitSelection={onClearGridSplitSelection}
          onClearLocalEditRegions={onClearLocalEditRegions}
          onExtractVideoFrame={onExtractVideoFrame}
          onSetLocalEditMode={onSetLocalEditMode}
          onSubmitLocalEdit={onSubmitLocalEdit}
          onToggleGridSplitSelection={onToggleGridSplitSelection}
          onUpdateLocalEditRegions={onUpdateLocalEditRegions}
          selected={selected}
        />
      </CanvasNodeShell>
    );
  }

  if (node.kind === "script") {
    return (
      <CanvasNodeShell {...shellProps}>
        <PresetScriptCanvasNode node={node} onOpenWorkflow={onOpenScriptWorkflow} onRun={onRunNode} onTextResourceChange={onTextResourceChange} selected={selected} />
      </CanvasNodeShell>
    );
  }

  const nodeType = getDraftString(node, "nodeType");
  const Icon = nodeType === "video-clip" ? Scissors : node.inputType === "audio" ? Music2 : node.inputType === "video" ? Video : node.kind === "text" ? FileText : node.kind === "preview" ? Video : ImageIcon;
  const isInput = node.kind === "input";
  const isWarm = node.kind === "text" || node.kind === "audio";
  const previewUrl = getDraftString(node, "thumbnailUrl") || getDraftString(node, "resultImage");
  return (
    <CanvasNodeShell {...shellProps}>
      {isInput ? (
        <div
          className={cn(
            "relative flex h-full w-full flex-col items-center justify-center overflow-hidden rounded-[4px] bg-[#f8f9ff] text-center text-[#2a2d3a]",
            selected && "outline outline-2 outline-[#8b96ff]"
          )}
        >
          {previewUrl ? (
            <>
              <img
                alt=""
                className="pointer-events-none absolute inset-0 h-full w-full object-cover opacity-28"
                draggable={false}
                onDragStart={preventNativeImageDrag}
                src={previewUrl}
              />
              <span className="absolute inset-0 bg-white/62" />
            </>
          ) : null}
          <span className="relative mb-3 flex h-8 w-8 items-center justify-center rounded-[8px] border border-[#dfe3ff] bg-white text-[#7a85ff]">
            <Icon className="h-4 w-4" />
          </span>
          <div className="relative font-semibold text-[14px]">{node.title}</div>
          <div className="relative mt-2 line-clamp-3 px-5 text-[11px] leading-5 text-[#6f7482]">{node.subtitle}</div>
          <button className="relative mt-3 h-8 rounded-[8px] border border-[#dfe3ff] bg-white px-4 text-[11px] text-brand-selection" type="button">
            选择文件
          </button>
        </div>
      ) : (
        <div
          className={cn(
            "relative flex h-full w-full items-center gap-4 overflow-hidden rounded-[26px] border bg-[#f6f7fb] px-5 text-[#20222a]",
            isWarm && "bg-[#fff0f3]",
            node.kind === "workflow" && "bg-[#f6f7fb]",
            selected ? "border-[#8b96ff]" : "border-white/45"
          )}
        >
          <div
            className={cn(
              "flex h-14 w-14 shrink-0 items-center justify-center rounded-full border border-black/5 bg-white/70 text-[#8b96ff] shadow-[inset_0_0_16px_rgba(255,255,255,0.7)]",
              isWarm && "text-[#ff9eae]"
            )}
          >
            {node.kind === "workflow" ? <GitBranch className="h-5 w-5" /> : <Icon className="h-5 w-5" />}
          </div>
          <div className="min-w-0 flex-1">
            <div className="mb-1 text-[12px] text-[#697080]">{node.subtitle || "工具"}</div>
            <div className="truncate font-semibold text-[20px] tracking-[0]">{node.title}</div>
          </div>
          <div className="flex h-[58px] w-8 items-center justify-center rounded-full border border-black/8 bg-white/62 text-center text-[13px] leading-4 text-[#272a32]">
            待<br />配置
          </div>
        </div>
      )}
    </CanvasNodeShell>
  );
}

