function TargetModuleHeroGraphic({ kind }: { kind: AddModuleKind }) {
  if (kind === "text" || kind === "script" || kind === "legacy-script") {
    return (
      <div className="flex w-[92px] flex-col gap-[9px]">
        {[70, 70, 70, 70, 43].map((width, index) => (
          <span className="h-[7px] rounded-full bg-white/16" key={`${width}-${index}`} style={{ width }} />
        ))}
      </div>
    );
  }

  if (kind === "image") {
    return <ImageIcon className="h-[92px] w-[92px]" strokeWidth={1.5} />;
  }

  if (kind === "audio") {
    return <Music2 className="h-[86px] w-[86px]" strokeWidth={1.5} />;
  }

  if (kind === "video") {
    return (
      <span className="flex h-20 w-20 items-center justify-center rounded-[8px] bg-white/18 text-[#242424]">
        <Play className="ml-1 h-11 w-11 fill-current" strokeWidth={0} />
      </span>
    );
  }

  if (kind === "director") {
    return (
      <div className="relative h-[92px] w-[112px] text-white/20">
        <span className="absolute left-7 top-1 h-[72px] w-[72px] rounded-[10px] border border-current" />
        <span className="absolute left-0 top-12 h-px w-[112px] bg-current" />
        <span className="absolute left-1/2 top-0 h-[92px] w-px bg-current" />
        <Settings2 className="absolute left-[42px] top-[30px] h-8 w-8" strokeWidth={1.4} />
      </div>
    );
  }

  return <Scissors className="h-[92px] w-[92px]" strokeWidth={1.4} />;
}

