function getNextDirectorCameraName(cameraNames: string[]) {
  const highestCameraIndex = cameraNames.reduce((highest, name) => {
    const match = /^机位(\d+)$/.exec(name);
    return match ? Math.max(highest, Number(match[1])) : highest;
  }, 0);

  return `机位${highestCameraIndex + 1}`;
}

function formatDirectorCameraShotTitle(title: string) {
  const match = /^(机位\d+)-shot-(\d+)$/.exec(title);
  return match ? `${match[1]}-截图${match[2]}` : title;
}

function getNextDirectorRoleName(roleNames: string[]) {
  const usedIndexes = roleNames
    .map((name) => {
      const match = /^角色([A-Z])$/.exec(name);
      return match ? match[1].charCodeAt(0) - 65 : -1;
    })
    .filter((index) => index >= 0);
  const nextIndex = Math.max(-1, ...usedIndexes) + 1;

  return nextIndex < 26 ? `角色${String.fromCharCode(65 + nextIndex)}` : `角色${nextIndex + 1}`;
}

