const ASSET_MANAGER_FILTERS = ["全部", "文本", "图片", "视频", "视频合成", "导演台", "音频", "脚本", "脚本（旧版）"];
const VIDEO_CANVAS_TUTORIAL_URL = "/help.html";

function CanvasAssetManagerPanel({
  nodes,
  onClose,
  onDuplicateNode,
  onRenameNode,
  onResizeStart,
  onSelectNode,
  panelWidth,
}: {
  nodes: CloneNode[];
  onClose: () => void;
  onDuplicateNode: (id: string) => void;
  onRenameNode: (id: string, title: string) => boolean;
  onResizeStart: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onSelectNode: (id: string) => void;
  panelWidth: number;
}) {
  const assetFilterRef = useRef<HTMLDivElement | null>(null);
  const canvasFilterRef = useRef<HTMLDivElement | null>(null);
  const moreMenuRef = useRef<HTMLDivElement | null>(null);
  const searchInputRef = useRef<HTMLInputElement | null>(null);
  const [activeTab, setActiveTab] = useState<"canvas" | "assets">("canvas");
  const [assetFilterOpen, setAssetFilterOpen] = useState(false);
  const [assetSearchQuery, setAssetSearchQuery] = useState("");
  const [collapsed, setCollapsed] = useState(false);
  const [editingNodeId, setEditingNodeId] = useState<string | null>(null);
  const [menuNodeId, setMenuNodeId] = useState<string | null>(null);
  const [renameDraft, setRenameDraft] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [filter, setFilter] = useState("全部");
  const nodeRowWidth = Math.max(0, panelWidth - 24);
  const nodeActionMoreLeft = Math.max(0, panelWidth - 74);
  const nodeActionLocateLeft = Math.max(0, panelWidth - 48);
  const visibleNodes = nodes.filter((node) => {
    if (filter === "全部") return true;
    const kind = getTargetModuleKind(node);
    if (filter === "文本") return kind === "text" || node.inputType === "text";
    if (filter === "图片") return kind === "image" || node.inputType === "image" || /图片|镜头|角色|场景/.test(node.title);
    if (filter === "视频") return kind === "video" || node.inputType === "video" || /视频/.test(node.title);
    if (filter === "视频合成") return kind === "video-clip";
    if (filter === "导演台") return kind === "director";
    if (filter === "音频") return kind === "audio" || node.inputType === "audio";
    if (filter === "脚本") return kind === "script" || /脚本|剧本/.test(node.title);
    return false;
  }).filter((node) => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return true;
    const kind = getTargetModuleKind(node) || node.inputType || node.kind;
    return `${node.title} ${node.subtitle || ""} ${kind}`.toLowerCase().includes(query);
  });

  useEffect(() => {
    if (searchOpen) searchInputRef.current?.focus();
  }, [searchOpen]);

  useEffect(() => {
    if (!assetFilterOpen && !menuNodeId && !showFilters) return;

    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target as Node | null;
      if (!target) return;
      if (canvasFilterRef.current?.contains(target)) return;
      if (assetFilterRef.current?.contains(target)) return;
      if (moreMenuRef.current?.contains(target)) return;
      setAssetFilterOpen(false);
      setMenuNodeId(null);
      setShowFilters(false);
    };

    document.addEventListener("pointerdown", handlePointerDown);
    return () => document.removeEventListener("pointerdown", handlePointerDown);
  }, [assetFilterOpen, menuNodeId, showFilters]);

  const startRename = (node: CloneNode) => {
    setEditingNodeId(node.id);
    setRenameDraft(node.title);
    setMenuNodeId(null);
  };

  const commitRename = () => {
    if (!editingNodeId) return;
    const success = onRenameNode(editingNodeId, renameDraft);
    if (success) {
      setEditingNodeId(null);
      setRenameDraft("");
    }
  };

  return (
    <section
      className="fixed left-0 top-0 z-[30] flex h-dvh flex-col overflow-hidden border-r border-[#363636] bg-[var(--video-surface-171717)] text-white shadow-none"
      data-canvas-overlay="true"
      style={{ width: panelWidth }}
    >
      <div className="relative h-[92px] shrink-0">
        <div className="absolute left-2 top-[52px] flex h-7 min-w-0 items-center gap-[9px] px-1">
          <input
            aria-label="工作区名称"
            className="h-5 w-[78px] truncate bg-transparent text-[13px] text-white/82 outline-none"
            readOnly
            value="未命名工作区"
          />
          <button className="flex h-7 w-[68px] items-center justify-center rounded-lg text-[13px] text-white hover:bg-white/10" type="button">
            画布 1
          </button>
        </div>
      </div>

      <div className="flex h-[50px] shrink-0 items-center justify-between border-y border-[#363636] px-2">
        <div className="flex items-center gap-2">
          <button
            className={cn(
              "h-[30px] rounded-lg px-2 text-[14px] transition-colors",
              activeTab === "canvas" ? "bg-white/15 text-white" : "bg-transparent text-white/90 hover:bg-white/10"
            )}
            onClick={() => {
              setActiveTab("canvas");
              setAssetFilterOpen(false);
              setMenuNodeId(null);
            }}
            type="button"
          >
            画布
          </button>
          <button
            className={cn(
              "h-[30px] rounded-lg px-2 text-[14px] transition-colors",
              activeTab === "assets" ? "bg-white/15 text-white" : "bg-transparent text-white/90 hover:bg-white/10"
            )}
            onClick={() => {
              setActiveTab("assets");
              setMenuNodeId(null);
              setShowFilters(false);
            }}
            type="button"
          >
            资产
          </button>
        </div>
        <button aria-label="资产管理" className="flex h-8 w-8 items-center justify-center rounded-lg text-white/80 hover:bg-white/10" onClick={onClose} type="button">
          <AssetGlyph />
        </button>
      </div>

      {activeTab === "canvas" ? (
        <>
          <div className="flex h-[52px] shrink-0 flex-col gap-2 px-2 py-3">
            <div className="flex min-h-7 w-full min-w-0 items-center justify-between gap-1 pl-2 pr-0">
              {searchOpen ? (
                <div className="flex min-w-0 flex-1 items-center gap-px">
                  <Search className="h-3 w-3 shrink-0 text-white/50" />
                  <input
                    aria-label="搜索画布元素"
                    className="h-5 w-[101px] bg-transparent text-[13px] text-white outline-none placeholder:text-white/40"
                    onChange={(event) => setSearchQuery(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Escape") {
                        setSearchOpen(false);
                        setSearchQuery("");
                      }
                    }}
                    placeholder="搜索节点"
                    ref={searchInputRef}
                    value={searchQuery}
                  />
                </div>
              ) : (
                <div className="flex min-w-0 items-center gap-0.5">
                  <span className="text-[13px] font-medium leading-normal text-[#919191]">画布元素</span>
                  <button
                    aria-label={collapsed ? "展开全部分组" : "收起全部分组"}
                    className="flex h-7 w-7 items-center justify-center rounded-lg text-white/85 hover:bg-white/10"
                    onClick={() => setCollapsed((value) => !value)}
                    type="button"
                  >
                    <ChevronDown className={cn("h-4 w-4 transition-transform", collapsed && "-rotate-90")} />
                  </button>
                </div>
              )}

              <div className="flex shrink-0 items-center gap-0.5">
                <div className="relative" ref={canvasFilterRef}>
                  <button
                    aria-label={`筛选类型：${filter}`}
                    className={cn(
                      "flex h-7 items-center justify-center rounded-lg text-[13px] text-white hover:bg-white/10",
                      searchOpen ? "w-7" : "w-[54px]",
                      showFilters && "bg-white/10"
                    )}
                    onClick={() => setShowFilters((value) => !value)}
                    type="button"
                  >
                    {searchOpen ? <Settings2 className="h-4 w-4" /> : filter}
                  </button>
                  {showFilters ? (
                    <div className="absolute left-0 top-8 z-[410] grid w-[180px] gap-1 rounded-[12px] border border-white/10 bg-[var(--video-surface-171717)] px-1 pb-[3px] pt-2 shadow-[0_18px_60px_rgba(0,0,0,0.44)]" role="menu">
                      {ASSET_MANAGER_FILTERS.map((item) => (
                        <button
                          className={cn(
                            "h-8 rounded-[8px] px-2 text-left text-[13px] text-white hover:bg-white/10",
                            item === filter && "bg-white/10"
                          )}
                          key={item}
                          onClick={() => {
                            setFilter(item);
                            setShowFilters(false);
                          }}
                          role="menuitem"
                          type="button"
                        >
                          {item}
                        </button>
                      ))}
                    </div>
                  ) : null}
                </div>
                <button
                  aria-label={searchOpen ? "关闭搜索" : "搜索节点"}
                  className="flex h-7 w-7 items-center justify-center rounded-lg text-white/85 hover:bg-white/10"
                  onClick={() => {
                    setSearchOpen((value) => !value);
                    if (searchOpen) setSearchQuery("");
                  }}
                  type="button"
                >
                  {searchOpen ? <X className="h-4 w-4" /> : <Search className="h-4 w-4" />}
                </button>
              </div>
            </div>
          </div>

          <div className="min-h-0 flex-1 overflow-y-auto px-2 py-2">
            {visibleNodes.length === 0 ? (
              <div className="mt-2 rounded-lg px-3 py-5 text-center text-[13px] text-white/36">暂无匹配节点</div>
            ) : (
              <div className="grid gap-0.5">
                {visibleNodes.map((node) => (
                  <div className="group/node relative flex h-10 w-full items-center gap-0.5 rounded-lg py-1 pl-0 pr-0 hover:bg-white/10" key={node.id}>
                    {editingNodeId === node.id ? (
                      <input
                        aria-label={`重命名节点 ${node.title}`}
                        className="ml-2 h-7 min-w-0 flex-1 rounded-[7px] border border-white/14 bg-black/22 px-2 text-[13px] text-white outline-none"
                        onChange={(event) => setRenameDraft(event.target.value)}
                        onKeyDown={(event) => {
                          if (event.key === "Enter") commitRename();
                          if (event.key === "Escape") {
                            setEditingNodeId(null);
                            setRenameDraft("");
                          }
                        }}
                        value={renameDraft}
                      />
                    ) : (
                      <button
                        aria-label={`定位到节点 ${node.title}`}
                        className="flex h-8 min-w-0 items-center rounded-lg pl-3 pr-[58px] text-left text-[13px] text-white"
                        onClick={() => onSelectNode(node.id)}
                        style={{ width: nodeRowWidth }}
                        type="button"
                      >
                        <span className="block min-w-0 truncate">{node.title}</span>
                      </button>
                    )}
                    {editingNodeId === node.id ? (
                      <>
                        <button aria-label="确认重命名" className="flex h-6 w-6 items-center justify-center rounded-md text-white/50 hover:bg-white/10 hover:text-white" onClick={commitRename} type="button">
                          <Check className="h-3.5 w-3.5" />
                        </button>
                        <button aria-label="取消重命名" className="flex h-6 w-6 items-center justify-center rounded-md text-white/50 hover:bg-white/10 hover:text-white" onClick={() => {
                          setEditingNodeId(null);
                          setRenameDraft("");
                        }} type="button">
                          <X className="h-3.5 w-3.5" />
                        </button>
                      </>
                    ) : (
                      <>
                        <button
                          aria-label="更多操作"
                          className="absolute top-2 flex h-6 w-6 items-center justify-center rounded-md text-white/40 hover:bg-white/10 hover:text-white"
                          onClick={() => setMenuNodeId((current) => current === node.id ? null : node.id)}
                          style={{ left: nodeActionMoreLeft }}
                          type="button"
                        >
                          ...
                        </button>
                        <button
                          aria-label={`定位到节点 ${node.title}`}
                          className="absolute top-2 flex h-6 w-6 items-center justify-center rounded-md text-white/40 hover:bg-white/10 hover:text-white"
                          onClick={() => onSelectNode(node.id)}
                          style={{ left: nodeActionLocateLeft }}
                          type="button"
                        >
                          ↗
                        </button>
                      </>
                    )}
                    {menuNodeId === node.id ? (
                      <div
                        className="absolute top-[38px] z-[410] grid w-[180px] gap-1 rounded-[12px] border border-white/10 bg-[var(--video-surface-171717)] px-1 pb-1 pt-2 shadow-[0_18px_60px_rgba(0,0,0,0.46)]"
                        ref={moreMenuRef}
                        role="menu"
                        style={{ left: nodeActionMoreLeft }}
                      >
                        <button className="h-8 rounded-[8px] px-2 text-left text-[13px] text-white hover:bg-white/10" onClick={() => startRename(node)} role="menuitem" type="button">
                          重命名
                        </button>
                        <button className="h-8 rounded-[8px] px-2 text-left text-[13px] text-white hover:bg-white/10" onClick={() => {
                          onDuplicateNode(node.id);
                          setMenuNodeId(null);
                        }} role="menuitem" type="button">
                          复制
                        </button>
                      </div>
                    ) : null}
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="flex min-h-0 flex-1 flex-col gap-3 px-2 py-3">
          <div className="flex h-[30px] items-center gap-1">
            <div className="relative h-[30px] min-w-0 flex-1">
              <input
                className="h-[30px] w-full rounded-lg border border-white/10 bg-white/8 px-3 pr-8 text-[13px] text-white outline-none placeholder:text-white/35"
                onChange={(event) => setAssetSearchQuery(event.target.value)}
                placeholder="请输入搜索内容"
                value={assetSearchQuery}
              />
              <button aria-label="搜索" className="absolute right-1 top-1 flex h-[22px] w-[22px] items-center justify-center rounded-md text-white/50 hover:bg-white/10 hover:text-white" type="button">
                <Search className="h-3.5 w-3.5" />
              </button>
            </div>
            <div className="relative" ref={assetFilterRef}>
              <button
                aria-label="筛选素材类型"
                className="flex h-7 w-7 items-center justify-center rounded-lg text-white/55 hover:bg-white/10 hover:text-white"
                onClick={() => setAssetFilterOpen((value) => !value)}
                type="button"
              >
                <Settings2 className="h-4 w-4" />
              </button>
              {assetFilterOpen ? (
                <div className="absolute left-0 top-[38px] z-[410] w-[322px] rounded-[12px] border border-white/10 bg-[var(--video-surface-212121)] p-4 shadow-[0_18px_60px_rgba(0,0,0,0.46)]" role="menu">
                  <div className="text-[14px] leading-5 text-white/50">标签</div>
                  <div className="mt-3 grid w-[192px] grid-cols-3 gap-x-2 gap-y-2">
                    {["其它", "人物", "场景", "物品", "风格", "音效"].map((tag) => (
                      <button className="h-8 rounded-lg text-[13px] text-white/78 hover:bg-white/10" key={tag} type="button">
                        {tag}
                      </button>
                    ))}
                  </div>
                  <div className="mt-5 flex justify-end gap-3">
                    <button className="h-8 rounded-lg px-3 text-[13px] text-white/55 hover:bg-white/10" onClick={() => setAssetFilterOpen(false)} type="button">
                      清空
                    </button>
                    <button className="h-8 rounded-lg px-3 text-[13px] text-white hover:bg-white/10" onClick={() => setAssetFilterOpen(false)} type="button">
                      应用
                    </button>
                  </div>
                </div>
              ) : null}
            </div>
          </div>

          <div className="flex min-h-0 flex-1 flex-col">
            <div className="tiny-scrollbar h-full overflow-y-auto overflow-x-hidden">
              <div className="flex min-h-[188px] flex-col items-center justify-center px-4 py-8 text-center text-[13px] text-white/45">
                暂无资产
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex h-[53px] shrink-0 items-center justify-between border-t border-[#363636] px-3 pb-3 pt-2 text-[12px] text-white/42">共 {nodes.length} 节点</div>
      <div
        aria-label="调整工作区面板宽度"
        aria-valuemax={ASSET_MANAGER_MAX_WIDTH}
        aria-valuemin={ASSET_MANAGER_MIN_WIDTH}
        aria-valuenow={panelWidth}
        className="workspace-panel-drawer-resize-handle absolute bottom-0 right-0 top-0 z-[100] w-3 shrink-0 cursor-col-resize touch-none select-none bg-transparent"
        onPointerDown={onResizeStart}
        role="separator"
        tabIndex={0}
      />
    </section>
  );
}

