function SkillsAccessModal({
  onClose,
  siteName,
}: {
  onClose: () => void;
  siteName: string;
}) {
  const skillsName = `${siteName} Skills`;
  type AccessKeyItem = {
    id: string;
    name: string;
    tokenPrefix: string;
    scopes: string[];
    lastUsedAt: string | null;
    expiresAt: string | null;
    revokedAt: string | null;
    createdAt: string;
  };
  const [accessKeys, setAccessKeys] = useState<AccessKeyItem[]>([]);
  const [createdToken, setCreatedToken] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isCreating, setIsCreating] = useState(false);
  const [revokingId, setRevokingId] = useState<string | null>(null);

  const loadAccessKeys = useCallback(async () => {
    setIsLoading(true);
    try {
      const response = await apiFetch("/api/user/access-keys", { cache: "no-store" });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok || !payload?.success) {
        throw new Error(payload?.error || "加载 Access Key 失败");
      }
      setAccessKeys(Array.isArray(payload.data) ? payload.data : []);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "加载 Access Key 失败");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadAccessKeys();
  }, [loadAccessKeys]);

  const handleCreateAccessKey = useCallback(async () => {
    setIsCreating(true);
    try {
      const response = await apiFetch("/api/user/access-keys", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: "OpenClaw",
          scopes: ["canvas:read", "canvas:write"],
          expiresInDays: 90,
        }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok || !payload?.success || !payload?.data?.token) {
        throw new Error(payload?.error || "创建 Access Key 失败");
      }
      setCreatedToken(String(payload.data.token));
      toast.success("Access Key 已创建，请立即复制并妥善保存");
      await loadAccessKeys();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "创建 Access Key 失败");
    } finally {
      setIsCreating(false);
    }
  }, [loadAccessKeys]);

  const handleRevokeAccessKey = useCallback(
    async (accessKeyId: string) => {
      if (!window.confirm("撤销后使用该 Key 的 OpenClaw 将立即失去访问权限，确定继续吗？")) {
        return;
      }
      setRevokingId(accessKeyId);
      try {
        const response = await apiFetch(`/api/user/access-keys/${accessKeyId}`, {
          method: "DELETE",
        });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok || !payload?.success) {
          throw new Error(payload?.error || "撤销 Access Key 失败");
        }
        setCreatedToken("");
        toast.success("Access Key 已撤销");
        await loadAccessKeys();
      } catch (error) {
        toast.error(error instanceof Error ? error.message : "撤销 Access Key 失败");
      } finally {
        setRevokingId(null);
      }
    },
    [loadAccessKeys]
  );

  const formatDate = (value: string | null) => {
    if (!value) return "-";
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? "-" : date.toLocaleString("zh-CN");
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/58" data-canvas-overlay="true">
      <div className="w-[600px] max-w-[calc(100vw-32px)] rounded-[8px] border border-white/10 bg-[var(--video-surface-262626)] px-4 py-5 text-white shadow-[0_30px_100px_rgba(0,0,0,0.58)]">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h2 className="text-[15px] font-semibold leading-none text-white">我的Access key</h2>
            <div className="mt-5 space-y-2 text-[13px] leading-none text-white/76">
              <p>· Access key 仅用于 {skillsName} 的调用授权使用，一旦传播给他人，有账号泄露的风险，请谨慎保管!</p>
              <p>· {skillsName} 是 {siteName} 提供给 agent 使用的入口，可在 openclaw 中调用，完成专业视频创作。</p>
              <p>
                · 安装使用请戳
                <button
                  className="ml-1 text-brand-selection underline-offset-2 hover:underline"
                  onClick={() =>
                    toast.info("安装包位于 integrations/openclaw，可通过 STDIO MCP 接入。")
                  }
                  type="button"
                >
                  接口文档
                </button>
              </p>
            </div>
          </div>
          <button className="rounded-[8px] p-2 text-white/54 hover:bg-white/8 hover:text-white" onClick={onClose} type="button">
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="mt-6 flex justify-end">
          <button
            className="h-8 rounded-[8px] bg-white px-4 text-[12px] font-semibold text-black hover:bg-white/90"
            disabled={isCreating}
            onClick={() => void handleCreateAccessKey()}
            type="button"
          >
            {isCreating ? "创建中..." : "创建新 Access Key"}
          </button>
        </div>

        {createdToken ? (
          <div className="mt-4 rounded-[8px] border border-brand-selection/40 bg-brand-accent/10 p-3">
            <div className="text-[12px] font-semibold text-white">仅显示一次，请立即复制</div>
            <div className="mt-2 flex items-center gap-2">
              <code className="min-w-0 flex-1 overflow-x-auto rounded bg-black/30 px-2 py-2 text-[11px] text-white/80">
                {createdToken}
              </code>
              <button
                className="flex h-8 shrink-0 items-center gap-1 rounded-[6px] bg-white px-2 text-[11px] font-medium text-black"
                onClick={() => {
                  void navigator.clipboard?.writeText(createdToken);
                  toast.success("Access Key 已复制");
                }}
                type="button"
              >
                <Copy className="h-3.5 w-3.5" />
                复制
              </button>
            </div>
          </div>
        ) : null}

        <div className="mt-4 overflow-hidden rounded-[8px] border border-white/8">
          <div className="grid h-11 grid-cols-[145px_1fr_130px_54px] bg-white/16 text-[12px] text-white/86">
            <div className="flex items-center px-3">名称 / 创建日期</div>
            <div className="flex items-center px-3">Access Key</div>
            <div className="flex items-center px-3">有效期</div>
            <div />
          </div>
          {isLoading ? (
            <div className="flex h-[66px] items-center justify-center text-white/45">
              <Loader2 className="h-4 w-4 animate-spin" />
            </div>
          ) : accessKeys.length === 0 ? (
            <div className="flex h-[66px] items-center px-4 text-[13px] text-white/45">
              暂无 Access Key
            </div>
          ) : (
            accessKeys.map((item) => {
              const isRevoked = Boolean(item.revokedAt);
              return (
                <div
                  className="grid min-h-[66px] grid-cols-[145px_1fr_130px_54px] border-white/8 border-t text-[11px]"
                  key={item.id}
                >
                  <div className="flex min-w-0 flex-col justify-center px-3">
                    <span className="truncate text-white/80">{item.name}</span>
                    <span className="mt-1 text-white/38">{formatDate(item.createdAt)}</span>
                  </div>
                  <div className="flex min-w-0 items-center px-3 text-white/60">
                    <code className="truncate">{item.tokenPrefix}••••••••</code>
                  </div>
                  <div className="flex flex-col justify-center px-3 text-white/48">
                    <span className={isRevoked ? "text-red-300/80" : undefined}>
                      {isRevoked ? "已撤销" : formatDate(item.expiresAt)}
                    </span>
                    {!isRevoked && item.lastUsedAt ? (
                      <span className="mt-1">使用于 {formatDate(item.lastUsedAt)}</span>
                    ) : null}
                  </div>
                  <div className="flex items-center justify-center">
                    {!isRevoked ? (
                      <button
                        aria-label="撤销 Access Key"
                        className="rounded p-2 text-white/40 hover:bg-red-500/10 hover:text-red-300"
                        disabled={revokingId === item.id}
                        onClick={() => void handleRevokeAccessKey(item.id)}
                        type="button"
                      >
                        {revokingId === item.id ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <Trash2 className="h-4 w-4" />
                        )}
                      </button>
                    ) : null}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
}

