function ImageNodePreview({ node }: { node: CloneNode }) {
  const mediaType = getDraftString(node, "mediaType") || node.inputType || "image";
  const url = getNodeMediaUrl(node);
  const sourceUrl = getNodeSourceMediaUrl(node);
  const rotation = Number(node.draftValues?.rotation || 0);
  const isNineGridComposite = Boolean(node.draftValues?.nineGridComposite);
  const cropTile = normalizeGridCropTile(node.draftValues?.cropTile);
  const gridCellVisual = node.draftValues?.gridCellVisual
    ? normalizeGridCellVisual(node.draftValues?.gridCellVisual)
    : null;

  if (!url && !isNineGridComposite) {
    return (
      <div className="flex h-[420px] items-center justify-center rounded-[8px] border border-white/8 bg-white/5 text-[14px] text-white/42">
        当前节点暂无可预览素材
      </div>
    );
  }

  return (
    <div className="rounded-[8px] border border-white/8 bg-[var(--video-surface-111)] p-3">
      {mediaType === "video" ? (
        <video className="max-h-[72vh] w-full rounded-[6px] object-contain" controls playsInline src={url} />
      ) : isNineGridComposite && url ? (
        <img
          alt={node.title}
          className="max-h-[72vh] w-full rounded-[6px] object-contain"
          src={url}
          style={{ transform: `rotate(${rotation}deg)` }}
        />
      ) : isNineGridComposite ? (
        <div className="relative aspect-video max-h-[72vh] w-full overflow-hidden rounded-[6px] bg-white">
          <NineGridCompositePreview node={node} sourceUrl={sourceUrl} />
        </div>
      ) : cropTile && url && gridCellVisual ? (
        <div className="relative aspect-square max-h-[72vh] w-full overflow-hidden rounded-[6px] bg-white">
          <GridCellImage alt={node.title} src={url} visual={gridCellVisual} />
        </div>
      ) : cropTile && url ? (
        <div className="relative aspect-square max-h-[72vh] w-full overflow-hidden rounded-[6px] bg-white">
          <CroppedGridTileImage alt={node.title} cropTile={cropTile} rotation={rotation} src={url} />
        </div>
      ) : (
        <img
          alt={node.title}
          className="max-h-[72vh] w-full rounded-[6px] object-contain"
          src={url}
          style={{ transform: `rotate(${rotation}deg)` }}
        />
      )}
    </div>
  );
}

